import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function combining a skewed quadratic bowl,
    sinusoidal modulation, and pairwise interactions to achieve target ELA features.

    The function is defined as:
    f(x) = quadratic_bowl(x) + 0.5 * np.sin(3 * quadratic_bowl(x)) + 0.2 * interaction_term(x) + skew_term(x)

    where:
    - quadratic_bowl(x) = sum((x_i)^2)
    - interaction_term(x) = sum(x_i * x_j), for all i < j
    - skew_term(x) = 0.1*abs(min(x))
    """
    def quadratic_bowl(x):
        return np.sum(x**2)

    def interaction_term(x):
        interaction = 0.0
        for i in range(len(x)):
            for j in range(i + 1, len(x)):
                interaction += x[i] * x[j]
        return interaction

    def skew_term(x):
      return 0.1*abs(min(x))

    return quadratic_bowl(x) + 0.5 * np.sin(3 * quadratic_bowl(x)) + 0.2 * interaction_term(x) + skew_term(x)
